WITH filtered_departments AS (SELECT *, ROUND(budget, 2) AS budget_rounded FROM departments WHERE dept_name = 'Legal'), dept_name_summary AS (SELECT dept_name, location, SUM(CASE WHEN location = 'New York' THEN budget ELSE 0 END) AS new_york_budget FROM filtered_departments GROUP BY dept_name, location) SELECT dept_name, location, new_york_budget FROM dept_name_summary WHERE new_york_budget >= 55
